import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./contrast.css";

export function AnimatedContrastIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="contrast" {...props}>
      <circle data-part="ring" cx="12" cy="12" r="9" />
      <path data-part="half" d="M12 3a9 9 0 0 1 0 18z" fill="currentColor" stroke="none" />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="contrast"] [data-part="half"] {
    --icon-turn: -180deg;
    animation-name: icon-turn;
    animation-duration: var(--icon-duration-long);
    animation-timing-function: var(--ease-icon);
  }
}
